function createUser(name) {
  if (!name || typeof name !== 'string' || name.trim() === '') throw new Error('invalid');
  return { name };
}
function updateUser(u, name) {
  if (!name || typeof name !== 'string' || name.trim() === '') throw new Error('invalid');
  u.name = name;
  return u;
}
module.exports = { createUser, updateUser };

